<?php
/** Market Desk contact-review register: administrators record local evidence and can find outstanding review work without sending email/SMS. */
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/workspace.php';

$administrator = require_role(['admin']);
$filters = contact_review_register_filters($_GET);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    try {
        record_account_contact_verification((int) ($_POST['user_id'] ?? 0), (int) $administrator['id'], (string) ($_POST['contact_scope'] ?? ''), (string) ($_POST['review_reason_code'] ?? ''), (string) ($_POST['verification_note'] ?? ''));
        flash('success', 'The local contact-verification record has been saved. Changed contact details will require a fresh review.');
    } catch (Throwable $exception) {
        flash('error', $exception->getMessage());
    }
    $postFilters = contact_review_register_filters($_POST);
    $query = contact_review_register_query($postFilters);
    redirect('admin/contact-verification.php' . ($query !== '' ? '?' . $query : ''));
}
$records = contact_review_register_rows($filters, 250);
$contactQuery = contact_review_register_query($filters);
workspace_open('Contact verification', 'contact_verification');
?>
<?php if (!account_contact_verification_is_available() || !contact_review_reason_codes_are_available()): ?><div class="flash flash-error">Contact verification is not ready. Import <code>database/migrations/20260826_add_account_contact_verifications.sql</code> and <code>database/migrations/20260826_add_contact_review_reason_codes.sql</code> into the selected <code>quetta_agrilink</code> database.</div><?php else: ?><section class="workspace-section"><div class="workspace-section-header"><div><p class="desk-kicker">Administrator accountability register</p><h2>Local contact verification</h2><p>Find outstanding local reviews by account, review state, or approved evidence. This register does not send a message or claim automatic verification.</p></div><div class="workspace-section-actions"><span class="status-pill"><?= count($records) ?> shown</span><a class="button button-quiet" href="<?= e(app_url('admin/contact-verification-export.php' . ($contactQuery !== '' ? '?' . $contactQuery : ''))) ?>">Export filtered CSV</a></div></div><form class="activity-date-filter" method="get"><label>Account search<input name="search" value="<?= e($filters['search']) ?>" maxlength="80" placeholder="Name, email, or phone"></label><label>Review state<select name="status"><option value="all">All review states</option><option value="needs_review" <?= $filters['status'] === 'needs_review' ? 'selected' : '' ?>>Needs review</option><option value="email_reviewed" <?= $filters['status'] === 'email_reviewed' ? 'selected' : '' ?>>Email reviewed</option><option value="phone_reviewed" <?= $filters['status'] === 'phone_reviewed' ? 'selected' : '' ?>>Phone reviewed</option><option value="fully_reviewed" <?= $filters['status'] === 'fully_reviewed' ? 'selected' : '' ?>>Fully reviewed</option></select></label><label>Evidence<select name="reason"><option value="">All evidence</option><?php foreach (contact_review_reason_catalog() as $code => $label): ?><option value="<?= e($code) ?>" <?= $filters['reason'] === $code ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="button button-quiet" type="submit">Filter register</button><a href="<?= e(app_url('admin/contact-verification.php')) ?>">Clear filters</a></form><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Account</th><th>Current contact status</th><th>Verification record</th><th>Administrator action</th></tr></thead><tbody><?php if ($records === []): ?><tr><td colspan="4">No active account matches this contact-review filter.</td></tr><?php else: foreach ($records as $record): ?><tr><td><strong><?= e($record['full_name']) ?></strong><br><span class="muted"><?= e($record['role_name']) ?></span><br><span class="muted"><?= e($record['email']) ?> · <?= e($record['phone']) ?></span></td><td><div class="contact-status-stack"><span class="status-pill <?= $record['verified_email_at'] !== null ? 'verified' : 'pending' ?>">Email <?= $record['verified_email_at'] !== null ? 'reviewed' : 'not reviewed' ?></span><span class="status-pill <?= $record['verified_phone_at'] !== null ? 'verified' : 'pending' ?>">Phone <?= $record['verified_phone_at'] !== null ? 'reviewed' : 'not reviewed' ?></span></div></td><td><?php if ($record['updated_at'] !== null): ?><strong class="muted"><?= e(contact_review_reason_label($record['review_reason_code'])) ?></strong><p class="verification-note"><?= e($record['verification_notes']) ?></p><small class="muted">Last recorded by <?= e($record['verified_by_name'] ?? 'administrator') ?> at <?= e(date('j M Y H:i', strtotime((string) $record['updated_at']))) ?></small><?php else: ?><span class="muted">No local contact review has been recorded.</span><?php endif; ?></td><td><form method="post" class="verification-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int) $record['id'] ?>"><input type="hidden" name="search" value="<?= e($filters['search']) ?>"><input type="hidden" name="status" value="<?= e($filters['status']) ?>"><input type="hidden" name="reason" value="<?= e($filters['reason']) ?>"><select name="contact_scope" required><option value="both">Email and phone</option><option value="email">Email only</option><option value="phone">Phone only</option></select><select name="review_reason_code" required><option value="">Choose local evidence</option><?php foreach (contact_review_reason_catalog() as $code => $label): ?><option value="<?= e($code) ?>"><?= e($label) ?></option><?php endforeach; ?></select><textarea name="verification_note" required maxlength="800" placeholder="Non-sensitive context only — never enter passwords, reset links, or tokens."></textarea><button class="button button-quiet" type="submit">Record contact review</button></form></td></tr><?php endforeach; endif; ?></tbody></table></div></section><?php endif; ?>
<?php workspace_close(); ?>
